/**
 * Shared Portfolio Core Script
 * Navigation, Mobile Sidebar, and Daily Drivers Belt
 */

// Mobile Sidebar Toggle
document.addEventListener('DOMContentLoaded', () => {
  const hamburger = document.getElementById('hamburger');
  const sidebar   = document.getElementById('sidebar');
  const overlay   = document.getElementById('sidebarOverlay');

  if (hamburger && sidebar && overlay) {
    hamburger.addEventListener('click', () => {
      sidebar.classList.toggle('open');
      overlay.classList.toggle('open');
    });
    overlay.addEventListener('click', closeSidebar);
  }
});

function closeSidebar() {
  const sidebar = document.getElementById('sidebar');
  const overlay = document.getElementById('sidebarOverlay');
  if (sidebar && overlay) {
    sidebar.classList.remove('open');
    overlay.classList.remove('open');
  }
}

// Daily Drivers Belt
const tools = [
      { name: 'Shopify', logo: 'data:image/png;base64,', color: '#96BF48' },
      { name: 'Shopify Flow', logo: 'data:image/png;base64,', color: '#5E8E3E' },
      { name: 'Matrixify', logo: 'data:image/png;base64,', color: '#5C6AC4' },
      { name: 'Klaviyo', logo: null, color: '#0F1B35', letter: 'KL' },
      { name: 'DSers', logo: null, color: '#FF6B35', letter: 'DS' },
      { name: 'Slack', logo: 'data:image/png;base64,', color: '#4A154B' },
      { name: 'Gorgias', logo: 'data:image/png;base64,', color: '#1A73E8' },
      { name: 'Claude', logo: null, color: '#CC785C', letter: 'AI' },
    ];
    function buildBelt() {
      const track = document.getElementById('beltTrack');
      if (!track) return;
      const doubled = [...tools, ...tools];
      track.innerHTML = doubled.map(t => {
        const icon = t.logo
          ? `<img src="${t.logo}" alt="${t.name}" style="width:24px;height:24px;object-fit:contain;" onerror="this.style.display='none';this.nextSibling.style.display='flex'">
             <div class="tool-icon-box" style="background:${t.color};display:none">${(t.letter||t.name.slice(0,2)).toUpperCase()}</div>`
          : `<div class="tool-icon-box" style="background:${t.color}">${(t.letter||t.name.slice(0,2)).toUpperCase()}</div>`;
        return `<div class="tool-chip">${icon}<span>${t.name}</span></div>`;
      }).join('');
    }

// Build Belt on Load if beltTrack exists
document.addEventListener('DOMContentLoaded', () => {
  buildBelt();
});
